<?php
require __DIR__.'/config/database.php';function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$rows=$pdo->query("SELECT c.id,c.ma_ca_thi,c.ngay_thi,c.gio_bat_dau,c.gio_ket_thuc,hp.ma_hoc_phan,hp.ten_hoc_phan,k.ten_ky_thi,p.ma_phong,p.suc_chua,(SELECT COUNT(*) FROM dang_ky_thi d WHERE d.ca_thi_id=c.id) si_so FROM ca_thi c JOIN hoc_phan hp ON hp.id=c.hoc_phan_id JOIN ky_thi k ON k.id=c.ky_thi_id JOIN phong_thi p ON p.id=c.phong_thi_id ORDER BY c.ngay_thi,c.gio_bat_dau")->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kỳ thi & ca thi - ExamFlow</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="layout"><aside class="sidebar"><div class="brand">▦ ExamFlow</div><a href="index.php">Tổng quan</a><a href="students.php">Sinh viên</a><a href="courses.php">Học phần</a><a class="active" href="exams.php">Kỳ thi & ca thi</a><a href="rooms.php">Phòng thi</a><a href="results.php">Kết quả thi</a></aside><main class="main"><div class="top"><div><h1>Kỳ thi & ca thi</h1><div class="muted">Lịch ca thi, học phần, phòng và sĩ số đã đăng ký.</div></div><a class="btn secondary" href="index.php">← Tổng quan</a></div><div class="panel"><h2>Danh sách ca thi (<?=count($rows)?>)</h2><?php if(!$rows):?><div class="empty">Chưa có ca thi.</div><?php else:?><table><thead><tr><th>Mã ca</th><th>Kỳ thi</th><th>Học phần</th><th>Ngày</th><th>Giờ</th><th>Phòng</th><th>Sĩ số / sức chứa</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['ma_ca_thi'])?></td><td><?=h($r['ten_ky_thi'])?></td><td><?=h($r['ma_hoc_phan'].' - '.$r['ten_hoc_phan'])?></td><td><?=h($r['ngay_thi'])?></td><td><?=h(substr($r['gio_bat_dau'],0,5).'–'.substr($r['gio_ket_thuc'],0,5))?></td><td><?=h($r['ma_phong'])?></td><td><?=h($r['si_so'].' / '.$r['suc_chua'])?></td></tr><?php endforeach?></tbody></table><?php endif?></div></main></div></body></html>
